CREATE TABLE IF NOT EXISTS `bans` ( `id` VARCHAR(16) , `player` VARCHAR(36) NOT NULL , `duration` DOUBLE NOT NULL , `creationdate` DATETIME NOT NULL , `creator` VARCHAR(36) NOT NULL , `reason` VARCHAR(100) NOT NULL , `ip` VARCHAR(100) NOT NULL , `type` VARCHAR(20) NOT NULL );
CREATE TABLE IF NOT EXISTS `banhistories` ( `id` VARCHAR(16) NOT NULL ,  `player` VARCHAR(36) NOT NULL , `duration` DOUBLE NOT NULL , `creator` VARCHAR(36) NOT NULL , `reason` VARCHAR(100) NOT NULL , `ip` VARCHAR(100) NOT NULL , `type` VARCHAR(20) NOT NULL , `creationdate` DATETIME NOT NULL );
CREATE TABLE IF NOT EXISTS `kicks` ( `player` VARCHAR(100) NOT NULL , `creator` VARCHAR(100) NOT NULL , `reason` VARCHAR(100) NOT NULL , `creationdate` DATETIME NOT NULL );
CREATE TABLE IF NOT EXISTS `logs` ( `id` INTEGER PRIMARY KEY AUTOINCREMENT, `action` VARCHAR(100) NOT NULL , `target` VARCHAR(100) NOT NULL , `creator` VARCHAR(100) NOT NULL , `note` VARCHAR(500) NOT NULL , `creationdate` DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS `bedrockplayer` ( `username` VARCHAR(64) NOT NULL , `uuid` VARCHAR(64) NOT NULL );
CREATE TABLE IF NOT EXISTS `unbans` (`id` VARCHAR(16) NOT NULL , `player` VARCHAR(36) NOT NULL , `unbanner` VARCHAR(36) NOT NULL , `creationdate` DATETIME NOT NULL , `reason` VARCHAR(1000) NOT NULL , `type` VARCHAR(20) NOT NULL );
